import{_ as a}from"./chunks/mac-security-settings.DOF-7oNi.js";import{_ as t,o as i,c as o,ae as s}from"./chunks/framework.Czhw_PXq.js";const q=JSON.parse(`{"title":"Problème courant d'installation sur macOS - Solution à \\"l'application est endommagée\\"","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/mac-installation-issue.md","filePath":"fr/guide/mac-installation-issue.md"}`),r={name:"fr/guide/mac-installation-issue.md"};function l(n,e,p,u,d,c){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="probleme-courant-d-installation-sur-macos-solution-a-l-application-est-endommagee" tabindex="-1">Problème courant d&#39;installation sur macOS - Solution à &quot;l&#39;application est endommagée&quot; <a class="header-anchor" href="#probleme-courant-d-installation-sur-macos-solution-a-l-application-est-endommagee" aria-label="Permalink to &quot;Problème courant d&#39;installation sur macOS - Solution à &quot;l&#39;application est endommagée&quot;&quot;">​</a></h1><p>Lorsque vous installez OTools ou d&#39;autres applications tierces sur macOS, vous pouvez rencontrer un message similaire à &quot;xxx.app est endommagé, impossible de l&#39;ouvrir, vous devriez le déplacer dans la corbeille&quot;. Cela est généralement dû aux paramètres de sécurité de macOS.</p><h2 id="pourquoi-cela-se-produit-il" tabindex="-1">Pourquoi cela se produit-il ? <a class="header-anchor" href="#pourquoi-cela-se-produit-il" aria-label="Permalink to &quot;Pourquoi cela se produit-il ?&quot;">​</a></h2><p>macOS a un contrôle très strict sur les programmes par rapport à Windows. Les applications non issues de l&#39;App Store affichent souvent des messages comme &quot;xxx.app est endommagé&quot; lors de l&#39;installation. Depuis macOS 10.15, Apple a encore restreint les autorisations pour les applications non signées, ce qui rend ces problèmes plus fréquents.</p><h2 id="solutions" tabindex="-1">Solutions <a class="header-anchor" href="#solutions" aria-label="Permalink to &quot;Solutions&quot;">​</a></h2><h3 id="methode-1-parametrage-permettant-d-autoriser-les-applications-telechargees-depuis-n-importe-ou" tabindex="-1">Méthode 1 : Paramétrage permettant d&#39;autoriser les applications téléchargées depuis &quot;N&#39;importe où&quot; <a class="header-anchor" href="#methode-1-parametrage-permettant-d-autoriser-les-applications-telechargees-depuis-n-importe-ou" aria-label="Permalink to &quot;Méthode 1 : Paramétrage permettant d&#39;autoriser les applications téléchargées depuis &quot;N&#39;importe où&quot;&quot;">​</a></h3><ol><li>Ouvrez &quot;Préférences Système -&gt; Sécurité et confidentialité -&gt; Général&quot;</li><li>Vérifiez si l&#39;option &quot;Autoriser les apps téléchargées depuis&quot; a déjà activé l&#39;option &quot;N&#39;importe où&quot;</li><li>Si ce n&#39;est pas activé, cliquez sur l&#39;icône du petit cadenas en bas à gauche pour déverrouiller, puis sélectionnez &quot;N&#39;importe où&quot;</li></ol><p><img src="'+a+'" alt=""></p><p>Si vous ne voyez pas l&#39;option &quot;N&#39;importe où&quot; dans les paramètres, ouvrez le Terminal et entrez la commande suivante :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span></code></pre></div><p>Entrez le mot de passe de connexion de votre ordinateur comme demandé, puis appuyez sur Entrée. Après cela, vous verrez apparaître l&#39;option &quot;N&#39;importe où&quot; dans les paramètres.</p><p>Normalement, après ce paramétrage, l&#39;application peut être installée normalement. Cependant, si votre version de macOS est plus récente, vous devrez peut-être toujours essayer la méthode suivante.</p><h3 id="methode-2-contourner-l-authentification-gatekeeper-d-apple" tabindex="-1">Méthode 2 : Contourner l&#39;authentification Gatekeeper d&#39;Apple <a class="header-anchor" href="#methode-2-contourner-l-authentification-gatekeeper-d-apple" aria-label="Permalink to &quot;Méthode 2 : Contourner l&#39;authentification Gatekeeper d&#39;Apple&quot;">​</a></h3><p>Si la Méthode 1 ne résout toujours pas le problème, vous pouvez essayer les étapes suivantes :</p><ol><li>Ouvrez le Terminal</li><li>Entrez la commande suivante, mais n&#39;appuyez pas encore sur Entrée :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span></span></code></pre></div><ol start="3"><li>Dans le Finder, localisez OTools.app dans le dossier Applications</li><li>Glissez OTools.app dans la fenêtre du Terminal, ce qui ajoutera automatiquement le chemin de l&#39;application à la commande</li><li>Appuyez sur Entrée, entrez votre mot de passe, et une fois terminé, vous pourrez exécuter directement l&#39;application</li></ol><h3 id="methode-3-clic-droit-pour-ouvrir-adapte-pour-la-premiere-installation" tabindex="-1">Méthode 3 : Clic droit pour ouvrir (adapté pour la première installation) <a class="header-anchor" href="#methode-3-clic-droit-pour-ouvrir-adapte-pour-la-premiere-installation" aria-label="Permalink to &quot;Méthode 3 : Clic droit pour ouvrir (adapté pour la première installation)&quot;">​</a></h3><p>Pour les premières installations, vous pouvez également essayer :</p><ol><li>Trouvez OTools.app dans le Finder</li><li>Cliquez avec le bouton droit (ou maintenez la touche Contrôle enfoncée tout en cliquant)</li><li>Sélectionnez &quot;Ouvrir&quot;</li><li>Cliquez sur &quot;Ouvrir&quot; dans la fenêtre contextuelle d&#39;avertissement de sécurité</li></ol><h2 id="remarques-importantes" tabindex="-1">Remarques importantes <a class="header-anchor" href="#remarques-importantes" aria-label="Permalink to &quot;Remarques importantes&quot;">​</a></h2><ul><li>OTools est une application de bureau légitime construite à l&#39;aide du framework Tauri</li><li>Votre ordinateur n&#39;est pas affecté par des logiciels malveillants</li><li>Ce problème est causé par les politiques de sécurité d&#39;Apple, et non par l&#39;application elle-même</li></ul>',22)])])}const g=t(r,[["render",l]]);export{q as __pageData,g as default};
